  .ew-toolbar[data-size="sm"] { --ew-spec-size: sm; }
  .ew-toolbar[data-size="md"] { --ew-spec-size: md; }
  .ew-toolbar:not([data-size]) { --ew-spec-size: md; }
  @media (prefers-reduced-motion: reduce) {
    .ew-toolbar, .ew-toolbar *, .ew-toolbar *::before, .ew-toolbar *::after {
      transition: none !important;
      animation: none !important;
    }
